package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"
)

func(a *app)stkPush(w http.ResponseWriter,r *http.Request){m,e:=body(r);if e!=nil{write(w,400,map[string]any{"error":"Invalid request body"});return};policy:=normalize(str(m,"policyNumber"));var premium float64;var status string;err:=a.db.QueryRow(r.Context(),`SELECT monthly_premium,status FROM insurance_policies WHERE policy_number=$1 AND is_deleted=false AND (tenant_slug=$2 OR tenant_slug='system_shared')`,policy,tenant(r)).Scan(&premium,&status);if err!=nil{write(w,404,map[string]any{"error":"Policy not found"});return};if premium<=0{premium=floatVal(m["amount"])};if premium<=0||str(m,"phoneNumber")==""{write(w,400,map[string]any{"error":"A valid amount and phone number are required"});return};ref:=fmt.Sprintf("INS%d",time.Now().UnixNano()%1000000000);_,e=a.db.Exec(r.Context(),`INSERT INTO insurance_payments(reference,policy_number,phone,amount,tenant_slug) VALUES($1,$2,$3,$4,$5)`,ref,policy,str(m,"phoneNumber"),premium,tenant(r));if e!=nil{write(w,500,map[string]any{"error":"Could not start payment"});return};payload,_:=json.Marshal(map[string]any{"Amount":fmt.Sprintf("%.0f",premium),"PhoneNumber":str(m,"phoneNumber"),"AccountReference":ref,"TransactionDesc":"Insurance contribution"});req,e:=http.NewRequestWithContext(r.Context(),"POST",strings.TrimRight(env("MPESA_SERVICE_URL","http://restpoint_mpesa_service:4040"),"/")+"/api/v1/stkpush",strings.NewReader(string(payload)));if e!=nil{write(w,502,map[string]any{"error":"Payment service unavailable","reference":ref});return};req.Header.Set("Content-Type","application/json");client:=&http.Client{Timeout:20*time.Second};resp,e:=client.Do(req);if e!=nil{write(w,502,map[string]any{"error":"Payment service unavailable","reference":ref});return};defer resp.Body.Close();var response map[string]any;if json.NewDecoder(resp.Body).Decode(&response)!=nil||resp.StatusCode>=300{write(w,502,map[string]any{"error":"Payment request was rejected","reference":ref});return};_,_=a.db.Exec(r.Context(),`UPDATE insurance_payments SET merchant_request_id=$1,checkout_request_id=$2,updated_at=now() WHERE reference=$3`,response["MerchantRequestID"],response["CheckoutRequestID"],ref);response["reference"]=ref;response["status"]="pending";write(w,200,response)}

func(a *app)paymentCallback(w http.ResponseWriter,r *http.Request){secret:=os.Getenv("MPESA_CALLBACK_SECRET");if secret!=""&&r.Header.Get("X-Mpesa-Callback-Secret")!=secret{write(w,401,map[string]any{"error":"Unauthorized"});return};m,e:=body(r);if e!=nil{write(w,400,map[string]any{"error":"Invalid request body"});return};ref:=str(m,"AccountReference");if ref==""{ref=str(m,"reference")};value:=m["ResultCode"];description:=str(m,"ResultDesc");receipt:=str(m,"MpesaReceiptNumber");if b,ok:=m["Body"].(map[string]any);ok{if cb,ok:=b["stkCallback"].(map[string]any);ok{value=cb["ResultCode"];description,_=cb["ResultDesc"].(string);if ref==""{ref=r.URL.Query().Get("reference")};if meta,ok:=cb["CallbackMetadata"].(map[string]any);ok{if items,ok:=meta["Item"].([]any);ok{for _,it:=range items{if pair,ok:=it.(map[string]any);ok&&pair["Name"]=="MpesaReceiptNumber"{receipt=fmt.Sprint(pair["Value"])}}}}}};code:=fmt.Sprint(value);state:="failed";if code=="0"||code=="0.0"{state="paid"};tag,e:=a.db.Exec(r.Context(),`UPDATE insurance_payments SET status=$1,result_code=$2,result_description=$3,mpesa_receipt=NULLIF($4,''),updated_at=now() WHERE reference=$5`,state,code,description,receipt,ref);if e!=nil{write(w,500,map[string]any{"error":"Could not record payment result"});return};if tag.RowsAffected()==0{write(w,404,map[string]any{"error":"Payment reference not found"});return};write(w,200,map[string]any{"success":true})}

func(a *app)paymentStatus(w http.ResponseWriter,r *http.Request){var ref,policy,status,receipt string;var amount float64;err:=a.db.QueryRow(r.Context(),`SELECT reference,policy_number,status,mpesa_receipt,amount FROM insurance_payments WHERE reference=$1 AND (tenant_slug=$2 OR tenant_slug='system_shared')`,r.PathValue("reference"),tenant(r)).Scan(&ref,&policy,&status,&receipt,&amount);if err!=nil{write(w,404,map[string]any{"error":"Payment not found"});return};write(w,200,map[string]any{"success":true,"reference":ref,"policyNumber":policy,"status":status,"receipt":receipt,"amount":amount})}
